// première ligne : l'intention, gardée seulement si elle est dans la liste
// lignes suivantes : la réponse à afficher, sans lien
const MOTS = ['inscription', 'connexion', 'deconnexion', 'mes_donnees', 'supprimer_compte',
  'confidentialite', 'aide', 'annuler', 'aucune'];
const brut = typeof $input.first().json.output === 'string' ? $input.first().json.output : '';
const mot = brut.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().split(/[\s.,;:!?]+/)[0];
const reponse = brut.trim().split('\n').slice(1).join(' ')
  .replace(/https?:\/\/\S+|www\.\S+/gi, '')
  .replace(/\s+/g, ' ').trim().slice(0, 400);
return [{ json: { intention: MOTS.includes(mot) ? mot : 'aucune', reponse } }];
